let resultados = [];

// Função "caçadora" que varre qualquer nível de profundidade do JSON
function buscarClientes(obj) {
    if (!obj) return;

    // Se encontrou um array, olha cada item dentro dele
    if (Array.isArray(obj)) {
        obj.forEach(item => buscarClientes(item));
    } 
    // Se encontrou um objeto, verifica se ele é o cliente
    else if (typeof obj === 'object') {
        // Verifica se é um objeto de cliente válido
        if (obj.nome && obj.saldo && obj.perfil) {
            resultados.push({
                nome: obj.nome,
                email: obj.email || "",
                saldo: obj.saldo,
                perfil: obj.perfil
            });
        } else {
            // Se não for um cliente, continua cavando nas propriedades
            for (const key in obj) {
                buscarClientes(obj[key]);
            }
        }
    }
}

// Roda a função para todos os itens que chegaram do Merge
for (const item of $input.all()) {
    buscarClientes(item.json);
}

// Entrega a lista limpa e empacotada para o Terceiro Code
return {
    json: {
        resultados: resultados
    }
};

// 1. Resgata o array 'resultados' gerado pelo Segundo CODE
const resultados = $json.resultados || [];

// 2. Função de normalização de moeda (exatamente como no print do instrutor)
function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// 3. Resgata a tabela de investimentos do primeiro node que leu o CSV
// IMPORTANTE: O nome entre parênteses deve ser exatamente o nome do node do CSV
const investimentos = $('CODE JS 1').all().map(item => item.json);

// 4. Mapeia e retorna UM ITEM por cliente para o n8n processar individualmente
const out = resultados.map(c => {
  // Executa a função do instrutor para converter "R$ 12.500,00" em 12500
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  // --- LÓGICA DE NEGÓCIO DA IA ---

  // Filtra investimentos cruzando perfil e saldo mínimo
  const investimentosRecomendados = investimentos.filter(inv => 
    inv.perfil === c.perfil && 
    saldoNum >= inv.minimo
  );

  // Formata os produtos para o prompt
  const produtosFormatados = investimentosRecomendados.length > 0 
    ? investimentosRecomendados.map(i => `- ${i.produto} (Rentabilidade: ${i.rentabilidade} | Mínimo: R$ ${i.minimo})`).join('\n')
    : "Nenhum produto atende ao saldo mínimo no momento. Sugira opções de poupança.";

  // Cria o prompt dinâmico que será lido pelo Agente LLM
  const promptLLM = `Você é um consultor financeiro de elite. Escreva um e-mail curto, persuasivo e amigável para o cliente abaixo:

- Nome: ${c.nome}
- Perfil: ${c.perfil}
- Saldo Atual: R$ ${saldoNum.toFixed(2)}

Recomende e explique brevemente as vantagens dos seguintes produtos selecionados para ele:
${produtosFormatados}

A mensagem deve explicar como esses produtos se alinham ao perfil de risco dele e terminar com um Call to Action. Assine como "Seu Assistente de Investimentos". Não invente produtos fora da lista.`;

  // Retorna o objeto estruturado que alimentará o Agente
  return {
    json: {
      cliente_nome: c.nome,
      cliente_email: c.email,
      perfil: c.perfil,
      saldo_original: c.saldo,
      saldo_formatado: saldoNum,
      prompt_llm: promptLLM
    }
  };
});

// Retorna a lista final. O n8n vai quebrar isso em 10 execuções separadas 
// (uma para cada cliente), enviando um prompt individual por vez para a IA.
return out;

var clientesOriginais = $('CODE JS 3').all();

var resultadosFinais = $input.all().map((item, index) => {
  var cliente = clientesOriginais[index] ? clientesOriginais[index].json : {};

  var respostaIA = {};
  var sucesso = false;

  try {
    var textoGerado = item.json.output[0].content[0].text;
    respostaIA = JSON.parse(textoGerado);
    sucesso = true;
  } catch (error) {
    respostaIA = {
      subject: "Erro na geração",
      text_body: "Não foi possível gerar a mensagem.",
      html_body: "Não foi possível gerar a mensagem."
    };
  }

  return {
    json: {
      ok: sucesso,
      to: cliente.cliente_email || cliente.email || "",
      subject: respostaIA.subject || "",
      text_body: respostaIA.text_body || "",
      html_body: respostaIA.html_body || "",

      meta: {
        nome: cliente.cliente_nome || cliente.nome || "",
        perfil: cliente.perfil || "",
        saldo: cliente.saldo_formatado || cliente.saldo || ""
      }
    }
  };
});

return resultadosFinais;

// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);
const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;
  return obj;
});

// ✅ Retorna um array de itens, cada um com 'json' = objeto único
return investimentos.map(item => ({ json: item }));

const items = $input.all();

// Mapeia todos os itens, extrai o html_body e junta tudo
const htmlCombinado = items
  .map(item => item.json.html_body)
  .filter(html => html !== undefined && html !== "") // Filtra itens vazios/com erro
  .join("<br><br><hr><br><br>"); // Insere uma linha horizontal entre cada e-mail

// Retorna tudo consolidado em 1 único item
return {
  json: {
    html_consolidado: htmlCombinado
  }
};
